{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance with index 1 is configured to have a public IP address, which increases the risk of unauthorized access to the instance."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The EC2 instances do not enforce the use of HTTP tokens for the Instance Metadata Service (IMDS), which can allow unauthorized access to sensitive metadata."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id = aws_subnet.my_subnet.id\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Removed the public IP association for the EC2 instance with index 1 and enforced the use of HTTP tokens for the Instance Metadata Service (IMDS) to enhance security."
}
